  const IMG = {"catalog":"data:image/jpeg;base64,","search":"data:image/jpeg;base64,","detail":"data:image/jpeg;base64,","request":"data:image/jpeg;base64,","requests":"data:image/jpeg;base64,","notif":"data:image/jpeg;base64,"};
  const C = {"fr":{"doctitle":"Guide JellyCrowd — Keeklah.tv","kicker":"Guide · Keeklah.tv","h1":"Demander des films &amp; séries en un clic","lede":"Keeklah.tv te laisse parcourir des milliers de films et séries — même ceux qui ne sont pas encore sur le serveur — et les demander en un clic. On récupère le média pour toi, et tu es prévenu dès que c'est prêt. Voici comment, pas à pas.","where":"Tout se passe dans la barre en haut de l'écran : <b>Catalogue</b>, <b>Calendrier</b> et <b>Mes demandes</b>. Ton espace de stockage restant s'affiche en haut à droite.","steps":[{"n":1,"title":"Ouvre le Catalogue","intro":"Clique sur <b>Catalogue</b> en haut. Tu tombes sur « Le plus demandé ici », puis les nouveautés classées par plateforme.","bullets":["Bascule entre <b>Films</b> et <b>Séries</b> en haut à gauche.","Affine avec les <b>genres</b>, les curseurs <b>Années</b> et <b>Note</b>, la <b>langue</b>, le <b>pays</b> et <b>Trier par</b>.","Le badge vert <b>« Disponible »</b> sur une affiche = c'est déjà sur le serveur, regardable tout de suite."],"figs":[["catalog","Le Catalogue : les filtres en haut, les affiches en dessous."]]},{"n":2,"title":"Cherche un titre précis","intro":"Un nom en tête ? Tape-le dans la barre <b>Rechercher des films et séries…</b> en haut à droite, puis valide.","bullets":[],"figs":[["search","Recherche « matrix ». La croix sur la puce efface la recherche."]]},{"n":3,"title":"Ouvre la fiche, puis demande","intro":"Clique sur <b>Détails</b> (ou sur l'affiche) : résumé, casting, note, liens TMDB / IMDb. Deux cas selon que le titre est déjà là ou non.","bullets":["<b>Déjà disponible</b> → <b>Ouvrir dans Jellyfin</b> pour le lancer, ou <b>Ajouter à ma bibliothèque</b> (il compte alors dans ton quota).","<b>Pas encore là</b> → un bouton vert <b>Demander</b>. Tu peux choisir une <b>date souhaitée</b>, puis valider. C'est tout&nbsp;!"],"figs":[["detail","Titre <b>déjà disponible</b> : lance-le ou ajoute-le à ta bibliothèque."],["request","Titre <b>pas encore là</b> : choisis une date si tu veux, puis clique <b>Demander</b>."]],"callout":{"icon":"⭐","html":"<b>Pas décidé ?</b> L'étoile <b>« Ajouter à ma liste »</b> met le titre de côté sans le demander — tu le retrouves via <b>Ma liste</b> dans les filtres."}},{"n":4,"title":"Suis tes demandes","intro":"L'onglet <b>Mes demandes</b> liste tout ce que tu as demandé, avec l'avancement de chacune et ton stockage utilisé en haut.","bullets":[],"figs":[["requests","« Mes demandes » : chaque ligne montre son statut. <b>Annuler</b> retire une demande."]],"callout":{"icon":"⏳","html":"<b>Ce n'est pas en temps réel.</b> L'avancement se rafraîchit avec un peu de retard — un film peut déjà être lisible avant d'être marqué « Disponible » ici. C'est normal."}},{"n":5,"title":"Sois prévenu par e-mail","intro":"Pour recevoir un e-mail quand un titre est prêt, clique sur la <b>cloche 🔔</b> en haut à droite, puis sur l'<b>engrenage ⚙</b> du panneau.","bullets":["Renseigne ton <b>adresse e-mail</b> et coche <b>M'envoyer des notifications</b>.","Choisis <b>ce qui déclenche un e-mail</b> : un titre demandé qui sort, une demande devenue disponible, une décision sur tes demandes, ou une alerte de quota.","Clique <b>Enregistrer</b>. Les alertes dans l'appli (la cloche) restent toujours actives, même sans e-mail."],"figs":[["notif","Cloche 🔔 → engrenage ⚙ : ton adresse e-mail et les cas qui te préviennent."]]}],"legend":{"title":"Comprendre les statuts","intro":"Les étiquettes de couleur dans « Mes demandes » t'indiquent où en est chaque titre :","items":[["Approuvée","p-blue","Validée. La récupération du média est lancée (ou programmée)."],["En attente","p-grey","En attente de validation par un admin — ou ton quota est plein (elle repart toute seule quand de la place se libère)."],["Manquant","p-amber","Validée, mais le fichier n'est pas encore arrivé : récupération en cours."],["Pas encore sorti","p-grey","Le film ou l'épisode n'est pas encore sorti. On attend la sortie."],["Planifié pour le…","p-purple","Récupération programmée à la date de sortie. Ça n'occupe pas ton quota d'ici là."],["Disponible","p-green","C'est bon&nbsp;! Le titre est prêt et regardable dans Keeklah.tv."]]},"quota":{"title":"Ton quota de stockage","body":"Chaque membre dispose d'un espace de stockage (par ex. <b>30&nbsp;Go</b>). La barre en haut à droite — et en haut de « Mes demandes » — montre ce que tes médias récupérés consomment.","barLabel":"Stockage utilisé","bullets":["Les titres <b>pas encore sortis</b> ne comptent <b>pas</b> tant qu'ils n'ont pas été récupérés.","Si tu atteins la limite, tes nouvelles demandes passent <b>En attente</b> et <b>repartent automatiquement</b> quand de l'espace se libère."]},"faqTitle":"Bon à savoir","faq":[["Comment je sais que ma demande est prête ?","Son statut passe à <b>Disponible</b> dans « Mes demandes », et si tu as mis ton e-mail (étape 5), tu reçois un message. Rappel : l'affichage a un léger retard."],["Puis-je demander une seule saison d'une série ?","Oui. Sur la fiche d'une série, choisis la saison (voire l'épisode) avant de demander. Chaque saison se suit séparément."],["J'ai demandé un film qui sort dans plusieurs mois, normal qu'il ne se télécharge pas ?","Oui. Il s'affiche <b>Planifié pour le…</b> et sera récupéré tout seul le jour de sa sortie. En attendant, il n'occupe pas ton quota."],["Une fiche a une erreur (titre, affiche) ?","Utilise <b>Signaler un problème</b> en haut de la fiche : l'admin est prévenu."]],"footer":"Guide d'utilisation JellyCrowd — Keeklah.tv. Les captures proviennent de l'interface réelle ; l'apparence peut légèrement évoluer selon la version.","langName":"FR"},"en":{"doctitle":"JellyCrowd Guide — Keeklah.tv","kicker":"Guide · Keeklah.tv","h1":"Request movies &amp; shows in one click","lede":"Keeklah.tv lets you browse thousands of movies and shows — even ones that aren't on the server yet — and request them in one click. We fetch the media for you and let you know the moment it's ready. Here's how, step by step.","where":"Everything happens in the bar at the top of the screen: <b>Catalogue</b>, <b>Calendar</b> and <b>My requests</b>. Your remaining storage shows in the top-right corner.","steps":[{"n":1,"title":"Open the Catalogue","intro":"Click <b>Catalogue</b> at the top. You'll land on “Most requested here”, then new arrivals grouped by platform.","bullets":["Switch between <b>Movies</b> and <b>Series</b> at the top left.","Narrow it down with <b>genres</b>, the <b>Years</b> and <b>Rating</b> sliders, <b>language</b>, <b>country</b> and <b>Sort by</b>.","A green <b>“Available”</b> badge on a poster means it's already on the server — watch it right away."],"figs":[["catalog","The Catalogue: filters up top, posters below."]]},{"n":2,"title":"Search for a specific title","intro":"Got a name in mind? Type it in the <b>Search movies and shows…</b> box at the top right, then confirm.","bullets":[],"figs":[["search","Searching “matrix”. The × on the chip clears the search."]]},{"n":3,"title":"Open the details, then request","intro":"Click <b>Details</b> (or the poster): synopsis, cast, rating, TMDB / IMDb links. Two cases, depending on whether the title is already there.","bullets":["<b>Already available</b> → <b>Open in Jellyfin</b> to play it, or <b>Add to my library</b> (it then counts toward your quota).","<b>Not there yet</b> → a green <b>Request</b> button. You can pick a <b>desired date</b>, then confirm. That's it!"],"figs":[["detail","An <b>already-available</b> title: play it or add it to your library."],["request","A title <b>not on the server yet</b>: pick a date if you like, then click <b>Request</b>."]],"callout":{"icon":"⭐","html":"<b>Not sure yet?</b> The <b>“Add to my list”</b> star sets a title aside without requesting it — find it again via <b>My list</b> in the filters."}},{"n":4,"title":"Track your requests","intro":"The <b>My requests</b> tab lists everything you've asked for, with each one's progress and your used storage up top.","bullets":[],"figs":[["requests","“My requests”: each row shows its status. <b>Cancel</b> removes a request."]],"callout":{"icon":"⏳","html":"<b>It's not live.</b> Progress refreshes with a slight delay — a film may already be playable before it's marked “Available” here. That's normal."}},{"n":5,"title":"Get notified by email","intro":"To get an email when a title is ready, click the <b>bell 🔔</b> at the top right, then the <b>gear ⚙</b> in the panel.","bullets":["Enter your <b>email address</b> and tick <b>Send me notifications</b>.","Choose <b>what triggers an email</b>: a requested title getting released, a request becoming available, a decision on your requests, or a quota alert.","Click <b>Save</b>. In-app alerts (the bell) always stay on, even without email."],"figs":[["notif","Bell 🔔 → gear ⚙: your email address and what notifies you."]]}],"legend":{"title":"Understanding the statuses","intro":"The coloured labels in “My requests” tell you where each title stands:","items":[["Approved","p-blue","Validated. Fetching the media has started (or is scheduled)."],["Pending","p-grey","Waiting for an admin to approve — or your quota is full (it resumes on its own once space frees up)."],["Missing","p-amber","Approved, but the file hasn't arrived yet: fetching in progress."],["Not yet released","p-grey","The film or episode isn't out yet. We wait for the release."],["Scheduled for…","p-purple","Fetch scheduled for the release date. It doesn't use your quota until then."],["Available","p-green","Done! The title is ready and watchable in Keeklah.tv."]]},"quota":{"title":"Your storage quota","body":"Every member gets a storage allowance (e.g. <b>30&nbsp;GB</b>). The bar at the top right — and atop “My requests” — shows what your fetched media uses.","barLabel":"Storage used","bullets":["Titles that are <b>not yet released</b> do <b>not</b> count until they've been fetched.","If you hit the limit, new requests go <b>Pending</b> and <b>resume automatically</b> once space frees up."]},"faqTitle":"Good to know","faq":[["How do I know my request is ready?","Its status turns to <b>Available</b> in “My requests”, and if you set your email (step 5) you get a message. Remember: the display lags a little."],["Can I request just one season of a series?","Yes. On a series page, pick the season (or episode) before requesting. Each season is tracked separately."],["I requested a film that comes out in months — normal it isn't downloading?","Yes. It shows <b>Scheduled for…</b> and will be fetched on its own on release day. Until then it uses none of your quota."],["A page has a mistake (title, poster)?","Use <b>Report a problem</b> at the top of the page: the admin is notified."]],"footer":"JellyCrowd user guide — Keeklah.tv. Screenshots come from the live interface; the look may change slightly between versions.","langName":"EN"}};

  function esc(){}
  function fig(lang, key, cap){
    const narrow = key === 'notif' ? ' narrow' : '';
    return '<figure><div class="shot'+narrow+'"><img loading="lazy" alt="" src="'+IMG[key]+'"></div><figcaption>'+cap+'</figcaption></figure>';
  }
  function render(lang){
    const t = C[lang];
    let h = '';
    h += '<header class="hero"><div class="wrap">'
      + '<span class="kicker">'+t.kicker+'</span>'
      + '<h1>'+t.h1+'</h1>'
      + '<p class="lede">'+t.lede+'</p>'
      + '<p class="where">'+t.where+'</p>'
      + '</div></header>';
    h += '<main class="wrap">';
    for (const s of t.steps){
      h += '<section class="step"><div class="step-head"><div class="num">'+s.n+'</div><div>'
        + '<h2>'+s.title+'</h2><p>'+s.intro+'</p></div></div><div class="body">';
      if (s.bullets && s.bullets.length){
        h += '<ul class="clean">'+s.bullets.map(b=>'<li>'+b+'</li>').join('')+'</ul>';
      }
      for (const [k,cap] of s.figs){ h += fig(lang,k,cap); }
      if (s.callout){ h += '<div class="callout"><span class="ic">'+s.callout.icon+'</span><p>'+s.callout.html+'</p></div>'; }
      h += '</div></section>';
    }
    // legend
    h += '<section class="legend-sec"><h2 class="sec">'+t.legend.title+'</h2><p class="sec-intro">'+t.legend.intro+'</p><div class="legend">'
      + t.legend.items.map(([lab,cls,desc])=>'<div class="lg"><span class="pill '+cls+'">'+lab+'</span><p>'+desc+'</p></div>').join('')
      + '</div></section>';
    // quota
    h += '<section class="quota-sec"><h2 class="sec">'+t.quota.title+'</h2>'
      + '<p class="sec-intro" style="margin-bottom:0">'+t.quota.body+'</p>'
      + '<div class="qbar-demo"><div class="qbar-label"><span>'+t.quota.barLabel+'</span><span>0 B / 30 GiB</span></div><div class="qbar"><span></span></div></div>'
      + '<ul class="clean">'+t.quota.bullets.map(b=>'<li>'+b+'</li>').join('')+'</ul></section>';
    // faq
    h += '<section class="faq-sec"><h2 class="sec">'+t.faqTitle+'</h2>'
      + t.faq.map(([q,a])=>'<details><summary>'+q+'</summary><p>'+a+'</p></details>').join('')
      + '</section>';
    h += '</main><footer><div class="wrap">'+t.footer+'</div></footer>';
    document.getElementById('app').innerHTML = h;
    document.title = t.doctitle;
    document.documentElement.lang = lang;
  }
  function setLang(lang){
    render(lang);
    document.querySelectorAll('.seg button').forEach(b=>b.setAttribute('aria-pressed', String(b.dataset.lang===lang)));
  }
  document.querySelectorAll('.seg button').forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.lang)));
  // default: browser language if English, else French
  setLang((navigator.language||'fr').toLowerCase().startsWith('en') ? 'en' : 'fr');
